# --- export / readonly ------------------------------------------------------
def builtins_listing_normalize(channel, data):
    # A bare readonly lists PPID with the rest, and the parent is a new
    # process every run: a pinned listing drifted each time it was asked.
    if channel == "stdout":
        return re.sub(rb'PPID="\d+"', b'PPID="<pid>"', data)
    return data


for name, modes in (("export", ALL), ("readonly", ALL)):
    builtins_add(Utility(
        name,
        options=(Option("-p"),),
        operands=(("v=1",), ("v",), ("v=1", "w=2"), ("v='a b'",), (),
                  ("1bad=x",)),
        stdin=("empty",), stderr="loose", modes=modes,
        script=builtins_wrap(
            name, prologue="v=old\n",
            report='printf "v=<%s>|w=<%s>\\n" "${v-unset}" "${w-unset}"\n'
                   + name + ' -p 2>/dev/null | /bin/grep -Eo "(v|w)=[^ ]*" '
                   '| /bin/sort | /bin/tr "\\n" "|"; echo\n'),
        normalize=builtins_listing_normalize, max_flags=1))
