def builtins_local_script(argv, stdin):
    return ("v=global; w=global2\nf() {\n"
            "local " + builtins_words(argv) + "\n"
            'printf "[%s]\\n" "$?"\n'
            'declare -p v 2>/dev/null; declare -p w 2>/dev/null\n'
            "}\nf\n"
            'printf "after:%s\\n" "$v"\n')


