                   ("-d", "2001-09-09 +1 day", "--debug", "+%F"), ("--resolution",), ("-d", "@1000000000", "--resolution"),
                   ("-x",), ("-d",), ("-r",), ("-f",), ("-I", "-R", "-d", "@0"), ("-R", "-I", "-d", "@0"), ("-u", "-d", "2001-09-09 12:00 +0200", "+%H %Z"),
