def text_random_lines(seed, count, longest, alphabet="abc"):
    rng = random.Random(seed)
    return ("\n".join("".join(rng.choice(alphabet) for _ in range(rng.randint(0, longest)))
                      for _ in range(count)) + "\n").encode()


