#       Files holding a NUL where GNU grep reads its buffers, for its binary
#       rule: GNU looks for a NUL in each read of 98304 bytes before searching
#       it, and from the first read holding one prints nothing more, saying
#       "binary file matches" once a line is selected. early_nul has its NUL
#       in the first read, after a matching line; late_nul in the second, so
#       the line before it prints and the ones after do not. A set of its own
#       so no pinned row of the text set moves.
FIXTURES["text_binary"] = {
    **FIXTURES["text"],
    "early_nul": b"alpha first\n" + (b"y" * 99 + b"\n") * 700 + b"\0\nalpha after\n",
    "late_nul": b"alpha first\n" + (b"y" * 99 + b"\n") * 1000 + b"\0\nalpha after\nalpha more\n",
    # Where the NULs end lines: z1's eight lines are ab, cd, ab, ab, three
    # empty ones and ef; z2's first x and y are two lines.
    "z1": b"ab\0cd\nab\0ab\n\0\0\nef\n",
    "z2": b"x\0y\nxy\n",
    "longnul": b"struct " + b"x" * 200000 + b"\0 struct\nstruct tail\n",
    "nulrun": b"a\n" + b"\0" * 5000 + b"\nb\n",
}

_TEXT_GREP_BINARY_EXTRA = tuple({"fixture": "text_binary", "argv": argv} for argv in (
    ("alpha", "late_nul"), ("-n", "alpha", "late_nul"), ("-c", "alpha", "late_nul"),
    ("-l", "alpha", "late_nul"), ("-L", "alpha", "early_nul"), ("-q", "alpha", "early_nul"),
    ("-I", "-n", "alpha", "late_nul"), ("-I", "-c", "alpha", "late_nul"), ("-I", "-l", "alpha", "late_nul"),
    ("-I", "-L", "alpha", "late_nul"), ("-I", "-q", "alpha", "late_nul"), ("-I", "-c", "alpha", "early_nul"),
    ("-I", "-L", "alpha", "early_nul"), ("alpha", "early_nul"), ("-o", "-b", "alpha", "late_nul"),
    ("-v", "-c", "zzz", "late_nul"), ("-v", "-n", "zzz", "early_nul"), ("-A1", "-n", "alpha", "late_nul"),
    ("--color=always", "alpha", "late_nul"), ("-m1", "alpha", "early_nul"), ("-H", "alpha", "early_nul", "a.txt"),
    ("-s", "alpha", "early_nul"), ("-a", "-I", "a", "binary"), ("-I", "-a", "a", "binary"),
    ("--binary-files=text", "-I", "a", "binary"), ("-I", "--binary-files=binary", "a", "binary"),
    ("--binary-files=without-match", "-c", "a", "binary", "a.txt"), ("-U", "a", "binary"), ("-z", "a", "nul_lines"),
    ("-x", "c", "nul_lines"), ("", "nul_lines"), ("-w", "-n", "alpha", "late_nul", "early_nul"),
    ("-F", "-e", "alpha", "-e", "zzz", "late_nul"), ("-i", "ALPHA", "late_nul"), ("-E", "al+pha", "early_nul"),
    ("-c", "ab", "z1"), ("-c", "", "z1"), ("-c", "^$", "z1"), ("-v", "-c", "ab", "z1"), ("-x", "-c", "ab", "z1"),
    ("-c", "^cd", "z1"), ("-c", "ab$", "z1"), ("-c", "x.y", "z2"), ("-l", "x.y", "z2"), ("-c", "-F", "-x", "x", "z2"),
    ("-c", "-w", "y", "z2"), ("-c", "struct", "longnul"), ("struct", "longnul"), ("-c", "^$", "nulrun"),
    ("-n", "b", "nulrun"), ("-c", "-a", "ab", "z1"), ("-o", "-c", "ab", "z1"), ("-c", "--color=always", "^$", "z1"),
    ("-l", "-A2", "^$", "z1"), ("-L", "-o", "^$", "z1"), ("-q", "-C1", "^$", "z1"), ("-c", "-o", "-v", "^$", "z1"),
    ("-c", "-B1", "b*", "z1"), ("-L", "zz", "z1"), ("-m1", "-c", "ab", "z1"), ("-c", "-z", "ab", "z1"),
    ("-I", "-c", "ab", "z1"), ("-I", "-L", "ab", "z1"), ("-c", "-v", "^$", "nulrun"),
))


#       The half of GNU's binary rule that a locale decides: in UTF-8 a line
#       holding a byte that is no character is kept from the output -- a
#       selected line, a line of context or an -o match -- and the file says
#       "binary file matches" once, though -c, -l and -I answer as before. The
#       grammar walk runs in the C locale, so these cells run as a check,
#       both programs under LC_ALL=C.UTF-8 in one directory.
_TEXT_GREP_ENCODING_FILES = {
    "bad1": b"struct \xff\nstruct ok\n",
    "bad2": b"ok one\nstruct \xff\nstruct two\nstruct three\n",
    "bad3": b"struct fine\nzzz \xff\nstruct after\n",
    "bad4": b"struct \xc3\nstruct \xc3\xa9\n",
    "bad5": b"struct a\nstruct \xff b\n\0\nstruct c\n",
    "bad8": b"struct one\nctx \xff\nstruct two\n",
    "badz": b"struct \xff\0struct ok\0",
}

_TEXT_GREP_ENCODING_CASES = (
    ("-n", "struct", "bad1"), ("-n", "struct", "bad2"), ("-n", "struct", "bad3"), ("-n", "zzz", "bad3"),
    ("-n", "struct", "bad4"), ("-n", "struct", "bad5"), ("-c", "struct", "bad2"), ("-l", "struct", "bad1"),
    ("-v", "-n", "zzz", "bad2"), ("-o", "-n", "struct", "bad2"), ("-A1", "-n", "ok", "bad2"),
    ("-a", "-n", "struct", "bad2"), ("-I", "-n", "struct", "bad2"), ("-I", "-c", "struct", "bad2"),
    ("-z", "struct", "badz"), ("-A1", "-n", "one", "bad8"), ("-B1", "-n", "two", "bad8"),
    ("-C1", "-n", "struct", "bad8"), ("--color=always", "struct", "bad2"), ("-I", "-A1", "-n", "one", "bad8"),
    ("-n", "struct", "bad2", "bad2"), ("-v", "-c", "zzz", "bad2"), ("-H", "-x", "struct two", "bad2"),
    ("-m1", "-n", "struct", "bad1"), ("-F", "-n", "struct", "bad2"), ("-s", "struct", "bad1"),
)


def text_grep_encoding(farm):
    import shutil
    import subprocess
    import tempfile

    reference = shutil.which("grep", path=os.defpath)
    candidate = Path(farm) / "grep"
    if not reference or not candidate.exists():
        return 0, 1, ["the UTF-8 grep cells need both a reference and a candidate grep"]
    environment = dict(os.environ, LC_ALL="C.UTF-8")
    environment.pop("GREP_COLORS", None)
    passed = 0
    notes = []
    with tempfile.TemporaryDirectory(prefix="grep-encoding-") as temporary:
        for name, data in _TEXT_GREP_ENCODING_FILES.items():
            (Path(temporary) / name).write_bytes(data)
        for argv in _TEXT_GREP_ENCODING_CASES:
            answers = []
            for binary in (reference, candidate):
                result = subprocess.run(["grep", *argv], executable=str(binary), cwd=temporary,
                                        env=environment, stdin=subprocess.DEVNULL,
                                        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
                answers.append((result.returncode, result.stdout, result.stderr))
            if answers[0] == answers[1]:
                passed += 1
            else:
                notes.append(f"grep {shlex.join(argv)} under C.UTF-8: "
                             f"reference={answers[0]!r}, candidate={answers[1]!r}")
    return passed, len(_TEXT_GREP_ENCODING_CASES), notes


#       What each filter says about an input it could not open or could
#       not read, byte for byte. Every other text case compares a diagnostic
#       as present or absent, so a filter that named a directory "Read error"
#       where GNU names the reason, or wrote a newline in a file name straight
#       to the terminal where coreutils quotes it, agreed with the reference
#       everywhere. The tools here are the ones the text lane walks, each
#       with the words it needs in front of a file operand.
_TEXT_FAILURE_TOOLS = (
    ("cat",), ("wc",), ("cut", "-c1"), ("nl",), ("od",), ("uniq",), ("paste",), ("fold",),
    ("expand",), ("unexpand",), ("base64",), ("base32",), ("pr",), ("ptx",), ("sum",),
    ("head",), ("tail",), ("fmt",), ("tac",), ("sort",), ("sed", "p"), ("rev",),
    ("grep", "x"), ("tsort",), ("cksum",), ("md5sum",), ("shuf",), ("tee",),
    ("head", "-c1"), ("tail", "-c1"), ("wc", "-l"), ("sort", "-m"), ("uniq", "-c"),
    ("tr", "a", "b"), ("cmp",),
)

#       The two programs that read two inputs side by side, each shape of
#       failing one or both: GNU stops at the first that fails, and names
#       only that one.
_TEXT_FAILURE_PAIRED = (("comm",), ("join",), ("comm", "-3"), ("join", "-a1"))

#       Names that differ only in what a quoting has to do with them: a
#       plain one, a blank, each quote, a newline, a tab, an escape, a
#       backslash, a byte outside ASCII, a dollar, and a newline at either
#       end, which is where a shell-escaped name loses its outer quote.
_TEXT_FAILURE_NAMES = (
    b"missing", b"sp ace", b"new\nline", b"q'x", b'd"q', b"tab\tx", b"e\x1bx", b"b\\s",
    b"h\xc3\xa9", b"a$b", b"\nlead", b"trail\n", b"q'\nx",
)

#       Where the answer is still this tool's own, and why: rev takes - as a
#       file name, and GNU tac's reason for a directory is the filesystem's
#       -- Invalid argument on ext4, Is a directory on tmpfs -- from a call
#       that is not the seek and read its source names.
_TEXT_FAILURE_KNOWN = {
    ("rev", "stdin-directory"), ("tac", "directory"), ("tac", "stdin-directory"),
    # cmp - with standard input a directory compares the one file with itself.
    ("cmp", "stdin-directory"),
}


def text_failure_cases():
    cases = []
    for tool in _TEXT_FAILURE_TOOLS:
        for name in _TEXT_FAILURE_NAMES:
            cases.append((tool, "missing", (name,), None))
            cases.append((tool, "missing-after", (b"a.txt", name), None))
        for name in (b"dir", b"d ir", b"new\ndir", b"q'dir"):
            cases.append((tool, "directory", (name,), None))
        cases.append((tool, "stdin-directory", (b"-",), b"dir"))
        cases.append((tool, "stdin-directory", (), b"dir"))
    for tool in _TEXT_FAILURE_PAIRED:
        for name in (b"dir", b"q'dir", b"new\ndir"):
            cases.append((tool, "directory-first", (name, b"a.txt"), None))
            cases.append((tool, "directory-second", (b"a.txt", name), None))
            cases.append((tool, "directory-both", (name, name), None))
        for name in _TEXT_FAILURE_NAMES[:4]:
            cases.append((tool, "missing-both", (name, b"a.txt", ), None))
            cases.append((tool, "missing-both", (name, name + b"2"), None))
        cases.append((tool, "stdin-directory", (b"-", b"a.txt"), b"dir"))
        cases.append((tool, "stdin-directory", (b"a.txt", b"-"), b"dir"))
    return [case for case in cases if (case[0][0], case[1]) not in _TEXT_FAILURE_KNOWN]


COLLATION_LOCALES = ("fr_FR.UTF-8", "en_US.UTF-8")
NUMERIC_LOCALES = COLLATION_LOCALES + ("sv_SE",)


def collation_locales(names=COLLATION_LOCALES):
    """The locales of the collation checks that this machine has: a name the
    C library cannot set answers 'C', so a locale is here when `locale
    charmap` says something else."""
    import subprocess

    have = []
    for name in names:
        try:
            done = subprocess.run(["locale", "charmap"], capture_output=True, timeout=10,
                                  env=dict(os.environ, LC_ALL=name))
        except OSError:
            return []
        if done.returncode == 0 and done.stdout.strip() not in (b"", b"ANSI_X3.4-1968"):
            have.append(name)
    return have


def collation_word(rnd):
    """A word over what collation ranks: both cases, accented characters as
    one character and as a base with a combining mark, digits, the
    punctuation that is ignored at the first level and some ligatures."""
    alpha = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    accented = ["\u00e9", "\u00e8", "\u00ea", "\u00eb", "\u00e0", "\u00e2", "\u00e4", "\u00f4",
                "\u00f6", "\u00fb", "\u00fc", "\u00e7", "\u00ef", "\u00f1", "\u00c9", "\u00c0",
                "\u00c7", "\u00d6", "e\u0301", "a\u0300", "u\u0308", "n\u0303", "E\u0301"]
    marks = list(" _-.,;:!?'()[]{}@#$%^&*+=<>|~`") + ["\u2019", "\u00df", "\u00e6", "\u0153", "ch",
                                                      "ll", "\u4e2d", "\u20ac"]
    out = []
    for _ in range(rnd.choice([1, 2, 3, 4, 5, 6, 8, 12])):
        pick = rnd.random()
        out.append(rnd.choice(alpha) if pick < 0.55 else rnd.choice(accented) if pick < 0.8
                   else rnd.choice(marks))
    return "".join(out)


def text_collation(farm):
    """sort, comm and join under the locales whose collation this machine
    has, against the reference: the order glibc's strcoll gives is the
    contract, so every option that compares text (-f -d -i -r -u -s -b -t,
    keys, -c, and -n -h -g, which read the locale's decimal point and
    thousands separator) is walked over seeded lists of words that rank
    differently by case, accent, combining mark and punctuation. A machine
    without the locales runs none of it and says nothing."""
    import random
    import shutil
    import subprocess
    import tempfile

    locales = collation_locales()
    if not locales:
        return 0, 0, []
    tools = {name: shutil.which(name, path=os.defpath) for name in ("sort", "comm", "join")}
    if not all(tools.values()) or not all((Path(farm) / name).exists() for name in tools):
        return 0, 1, ["collation checks need sort, comm and join on both sides"]

    def run(binary, args, locale, data=None):
        try:
            done = subprocess.run([binary, *args], input=data, capture_output=True, timeout=60,
                                  env=dict(os.environ, LC_ALL=locale))
        except subprocess.TimeoutExpired:
            return (-1, b"timeout")
        return (done.returncode, done.stdout)

    passed = total = 0
    notes = []
    rnd = random.Random(0x434f4c4c)

    def same(tool, args, locale, data=None):
        nonlocal passed, total
        total += 1
        want = run(tools[tool], args, locale, data)
        got = run(str(Path(farm) / tool), args, locale, data)
        if want == got:
            passed += 1
        elif len(notes) < 12:
            notes.append(f"{tool} {' '.join(args)} under {locale}: status {want[0]} against {got[0]}, "
                         f"output {want[1][:60]!r} against {got[1][:60]!r}")

    for locale in locales:
        for size in (60, 400, 1500):
            words = [collation_word(rnd) for _ in range(size)]
            words += rnd.sample(words, size // 5)
            data = ("\n".join(words) + "\n").encode("utf-8")
            for args in ([], ["-r"], ["-u"], ["-f"], ["-d"], ["-i"], ["-fu"], ["-k1,1"], ["-t", " ", "-k2"],
                         ["-s", "-k1,1"], ["-fdr"], ["-b", "-k1"], ["-c"], ["-M"], ["-V"], ["-m"]):
                same("sort", args, locale, data)
        with tempfile.TemporaryDirectory(prefix="text-collation-") as directory:
            words = sorted({collation_word(rnd) for _ in range(300)})
            ordered = run(tools["sort"], [], locale, ("\n".join(words) + "\n").encode("utf-8"))[1]
            names = [Path(directory, f"{n}.txt") for n in range(2)]
            half = ordered.split(b"\n")[:-1]
            for path in names:
                keep = [line for line in half if rnd.random() < 0.6]
                path.write_bytes(b"".join(line + b"\n" for line in keep))
            for args in ([], ["-1"], ["-3"], ["-12"], ["-23"], ["--check-order"], ["--nocheck-order"]):
                same("comm", [*args, *map(str, names)], locale)
            for path, tag in zip(names, (b"1", b"2")):
                path.write_bytes(b"".join(line.replace(b" ", b"_") + b" " + tag + b"\n"
                                          for line in path.read_bytes().split(b"\n")[:-1]))
            for args in ([], ["-i"], ["-a1"], ["-v2"], ["-o", "1.1,2.2"],
                         ["-e", "X", "-a1", "-a2", "-o", "0,1.2,2.2"]):
                same("join", [*args, *map(str, names)], locale)

    # A number as the locale writes it: a separator inside the digits
    # and a decimal point that is a comma, and the other one as text.
    for locale in collation_locales(NUMERIC_LOCALES):
        def number():
            sign = rnd.choice(["", "-", "-", " ", "  "])
            digits = "".join(rnd.choice("0123456789") for _ in range(rnd.choice([0, 1, 2, 3, 4, 6])))
            if len(digits) > 3 and rnd.random() < 0.4:
                digits = digits[:-3] + rnd.choice([",", " ", "\u00a0", ".", "\u202f", "'"]) + digits[-3:]
            fraction = ""
            if rnd.random() < 0.4:
                fraction = rnd.choice([".", ","]) + "".join(rnd.choice("0123456789")
                                                          for _ in range(rnd.choice([0, 1, 2, 4])))
            return sign + digits + fraction + rnd.choice(["", "", "", "K", "M", "G", "k", "x", " x", "KiB"])

        encoding = "latin-1" if locale == "sv_SE" else "utf-8"
        for size in (40, 300):
            data = ("\n".join(number() for _ in range(size)) + "\n").encode(encoding, errors="replace")
            for args in (["-n"], ["-nr"], ["-h"], ["-hr"], ["-g"], ["-gr"], ["-n", "-u"], ["-h", "-u"],
                         ["-k1n"], ["-k1,1h"], ["-nb"]):
                same("sort", args, locale, data)
    return passed, total, notes


def text_file_failures(farm):
    """Every text tool on a missing name, a directory and a standard input
    that is a directory, over names that need each kind of quoting, against
    GNU with the diagnostic compared exactly."""
    import shutil
    import subprocess
    import tempfile
    from concurrent.futures import ThreadPoolExecutor

    cases = text_failure_cases()
    names = sorted({case[0][0] for case in cases})
    reference = {tool: shutil.which(tool, path=os.defpath) for tool in names}
    candidate = {tool: Path(farm) / tool for tool in names}
    if not all(reference.values()) or not all(p.exists() for p in candidate.values()):
        return 0, 1, ["text failure checks need " + ", ".join(names) + " on both sides"]

    def run(case, side):
        tool, _, operands, stdin = case
        with tempfile.TemporaryDirectory(prefix="text-failures-") as directory:
            Path(directory, "a.txt").write_bytes(b"alpha\nbeta\n")
            for name in (b"dir", b"d ir", b"new\ndir", b"q'dir"):
                os.mkdir(os.path.join(os.fsencode(directory), name))
            source = os.open(os.path.join(directory, stdin.decode()), os.O_RDONLY) if stdin \
                else subprocess.DEVNULL
            try:
                binary = str(side[tool[0]])
                result = subprocess.run([tool[0].encode(), *(a.encode() for a in tool[1:]), *operands],
                                        executable=binary, cwd=directory,
                                        env={"PATH": os.defpath, "LC_ALL": "C", "TZ": "UTC0"},
                                        stdin=source, stdout=subprocess.PIPE,
                                        stderr=subprocess.PIPE, timeout=10)
            finally:
                if stdin:
                    os.close(source)
            #       tee copies standard input into its operands and ptx and
            #       sort -m hold nothing back, so the directory's path cannot
            #       reach either stream; only the program's own spelling of
            #       its path is taken out of the diagnostic.
            return result.returncode, result.stdout, _stderr_exact(result.stderr)

    def compare(case):
        return case, run(case, reference), run(case, candidate)

    passed, notes = 0, []
    with ThreadPoolExecutor(max_workers=8) as pool:
        for case, want, got in pool.map(compare, cases):
            if want == got:
                passed += 1
            elif len(notes) < 40:
                tool, kind, operands, stdin = case
                shown = " ".join([*tool, *(repr(o)[1:] for o in operands)])
                notes.append(f"{shown} ({kind}): GNU {want!r} ours {got!r}")
    return passed, len(cases), notes


#       What grep asks its engines, over a log-shaped file whose first line is
#       dear for the graph and whose others are cheap: the graph gives up on the
#       first, the machine is put ahead of it, and a probe puts it back some
#       lines later. Shapes are the ones the machine, the graph and the required
#       string each answer, in every output mode, against GNU; a policy that
#       moved a line between engines and changed an answer is red here.
_TEXT_ENGINE_PATTERNS = (
    r'^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+ .*" 500 ', r'^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+ .*" [5]00 ',
    r'[0-9]{3} [0-9]{4,5} "[a-z]+ (error|info)', r'error|warning.*timeout', r'[z]{3}',
    r'user session [a-z]+ cache', r'timeout [a-z]+ refused', r'slow query.*fast',
    r'orders/[0-9]+ HTTP', r'GET /api/v1/(users|orders/[0-9]+) HTTP/1\.1" (404|500)',
    r'[0-9]+ [0-9]+ "[a-z ]+(east|west)$', r'\.[0-9]+ - - \[1[0-9]/Sep',
    r'orders/[0-9]+ .*" 404', r'timeout [a-z ]+ refused', r'(orders|users)/[0-9]+ (HTTP|ftp)',
    r'"[a-z]+ (error|info)"?$', r'^$', r'x*', r'(a+)+b', r'[0-9]+.*[0-9]+.*"$',
)
_TEXT_ENGINE_MODES = (("-c",), ("-n",), ("-v", "-c"), (), ("-o",), ("-v",), ("-l",),
                      ("-w", "-c"), ("-x", "-c"), ("-i", "-c"), ("-ow",), ("-vn",))


def text_engine_file():
    words = ("error", "info", "warning", "timeout", "east", "west", "refused", "cache")
    lines = ["orders/1 " * 400]
    for i in range(3000):
        lines.append(f'10.0.{i % 256}.{i % 97} - - [1{i % 9}/Sep/2026:10:{i % 60:02d}:00] '
                     f'"GET /api/v1/{("users", "orders")[i % 2]}/{i} HTTP/1.1" {(200, 404, 500, 500, 302)[i % 5]} '
                     f'{i * 7 % 9999} "{words[i % 8]} {words[(i * 3) % 8]}" {"slow query fast" if i % 41 == 0 else "user session x cache"} '
                     f'{"timeout ab refused" if i % 53 == 0 else ""}{"zzz" if i % 211 == 0 else ""}')
        if i == 1500:
            lines.append("timeout " * 300)
    return ("\n".join(lines) + "\n").encode()


def text_grep_engine(farm):
    import shutil
    import subprocess
    import tempfile
    from concurrent.futures import ThreadPoolExecutor

    reference = shutil.which("grep", path=os.defpath)
    candidate = Path(farm) / "grep"
    if not reference or not candidate.exists():
        return 0, 1, ["the engine cells need both a reference and a candidate grep"]
    environment = dict(os.environ, LC_ALL="C")
    with tempfile.TemporaryDirectory(prefix="grep-engine-") as temporary:
        log = text_engine_file()
        (Path(temporary) / "log").write_bytes(log)
        (Path(temporary) / "log2").write_bytes(log[len(log) // 3:])
        (Path(temporary) / "logz").write_bytes(log.replace(b"\n", b"\0"))
        (Path(temporary) / "nonl").write_bytes(log.rstrip(b"\n"))
        #       Two letters, and patterns whose machine has thousands of states:
        #       the cache is emptied and begun again under the four walks of a
        #       span, each of which starts over at its own record.
        state, lines = 12345, []
        for _ in range(500):
            row = []
            for _ in range(20 + state % 240):
                state = (state * 1103515245 + 12345) & 0x7FFFFFFF
                row.append("ab"[state >> 16 & 1])
            lines.append("".join(row))
        (Path(temporary) / "ab").write_text("\n".join(lines) + "\n")
        cases = [(("-E", *mode, "-e", pattern, "log"), None)
                 for pattern in _TEXT_ENGINE_PATTERNS for mode in _TEXT_ENGINE_MODES]
        cases += [(("-E", *mode, "-e", pattern, "ab"), None)
                  for pattern in ("(a|b)*a(a|b){12}b", "^(a|b)*a(a|b){11}b", "a(a|b){13}$")
                  for mode in (("-c",), ("-n",), ("-v", "-c"), ("-o",), ("-x", "-c"))]
        #       What the blocks of a span hand the printer, in every way the
        #       printer asks for them: a limit, an offset, context, two files, a
        #       colour, the other delimiter, no last newline, and a pipe.
        for pattern in (r'^[0-9.]+ .*" [5]00 ', r'error|warning.*timeout', r'[0-9]{3} [0-9]{4,5} "[a-z]+ (error|info)'):
            for extra, name, source in (
                (("-m", "2"), "log", None), (("-c", "-m", "3"), "log", None),
                (("-v", "-m", "3"), "log", None), (("-b",), "log", None), (("-bo",), "log", None),
                (("-A1",), "log", None), (("-B1",), "log", None), (("-C1", "-n"), "log", None),
                (("-H", "-c"), "log2", "log"), (("--color=always", "-o"), "log", None),
                (("-z", "-c"), "logz", None), (("-z", "-v", "-c"), "logz", None), ((), "nonl", None),
                (("-c",), "nonl", None), (("-v", "-c"), "nonl", None), (("-c",), None, "log"),
                (("-n",), None, "log"), (("-l",), "log", None), (("-q",), "log", None),
            ):
                operands = [name] if name else []
                if source and name:
                    operands.insert(0, source)
                cases.append((("-E", *extra, "-e", pattern, *operands), source if not name else None))

        def run(case):
            argv, source = case
            answers = []
            for binary in (reference, candidate):
                stdin = open(Path(temporary) / source, "rb") if source else subprocess.DEVNULL
                try:
                    result = subprocess.run(["grep", *argv], executable=str(binary), cwd=temporary,
                                            env=environment, stdin=stdin, stdout=subprocess.PIPE,
                                            stderr=subprocess.PIPE, timeout=20)
                finally:
                    if source:
                        stdin.close()
                answers.append((result.returncode, result.stdout, result.stderr))
            return argv, answers

        passed, notes = 0, []
        with ThreadPoolExecutor(max_workers=8) as pool:
            for argv, answers in pool.map(run, cases):
                if answers[0] == answers[1]:
                    passed += 1
                elif len(notes) < 40:
                    notes.append(f"grep {shlex.join(argv)}: reference={answers[0][:2]!r}"
                                 f" ({len(answers[0][1])} bytes), candidate={answers[1][:2]!r}"
                                 f" ({len(answers[1][1])} bytes)")
    return passed, len(cases), notes


