KERNEL_PORTS_ARENA_TEST = r"""
int ext4_dir_open(struct inode *inode, struct file *file);
void free_rb_tree_fname(struct rb_root *root);
int ext4_htree_store_dirent(struct file *dir_file, __u32 hash, __u32 minor_hash, struct ext4_dir_entry_2 *dirent, struct fscrypt_str *ent_name);

static int same_trees(struct dir_private_info *a, struct dir_private_info *b, char *why)
{
        struct rb_node *x = a->root.rb_node, *y = b->root.rb_node;
        while (x && x->rb_left) x = x->rb_left;
        while (y && y->rb_left) y = y->rb_left;
        int at = 0;
        for (; x && y; x = rb_next(x), y = rb_next(y), at++) {
                struct fname *f = rb_entry(x, struct fname, rb_hash), *g = rb_entry(y, struct fname, rb_hash);
                for (int k = 0; f || g; f = f ? f->next : NULL, g = g ? g->next : NULL, k++) {
                        if (!f || !g) { sprintf(why, "chain %d of node %d is %s", k, at, f ? "longer" : "shorter"); return 0; }
                        if (f->hash != g->hash || f->minor_hash != g->minor_hash || f->inode != g->inode || f->name_len != g->name_len || f->file_type != g->file_type
                            || memcmp(f->name, g->name, f->name_len + 1)) { sprintf(why, "node %d entry %d differs (hash %x/%x len %u/%u type %u/%u)", at, k, f->hash, g->hash, f->name_len, g->name_len, f->file_type, g->file_type); return 0; }
                }
        }
        if (x || y) { sprintf(why, "the trees have different lengths"); return 0; }
        return 1;
}

int main(int argc, char **argv)
{
        long iters = argc > 1 ? atol(argv[1]) : 3000, bad = 0, stored = 0;
        for (long it = 0; it < iters; it++) {
                int m = rnd() % 4 == 0 ? rnd() % 300 : rnd() % 40;
                struct ext4_dir_entry_2 *de = calloc(m + 1, sizeof *de);
                struct fscrypt_str *nm = calloc(m + 1, sizeof *nm);
                u32 seen[64]; int ns = 0;
                for (int i = 0; i < m; i++) {
                        int len = rnd() % 5 == 0 ? 1 + rnd() % 255 : 1 + rnd() % 30;
                        de[i].inode = rnd(); de[i].file_type = rnd() % 4 ? rnd() % 8 : rnd();
                        nm[i].name = malloc(len); nm[i].len = len;
                        for (int k = 0; k < len; k++) nm[i].name[k] = rnd();
                }
                u32 hash[m + 1], minor[m + 1];
                for (int i = 0; i < m; i++) {
                        if (ns && rnd() % 7 == 0) { hash[i] = seen[rnd() % ns]; minor[i] = rnd() % 2 ? 0 : rnd(); }
                        else { hash[i] = (rnd() << 1) | (rnd() & 1); minor[i] = rnd() % 3 ? 0 : rnd(); if (ns < 64) seen[ns++] = hash[i]; }
                }
                struct inode inode; struct file fa, fc; memset(&inode, 0, sizeof inode); memset(&fa, 0, sizeof fa); memset(&fc, 0, sizeof fc);
                MA.live = MA.allocs = MA.frees = 0; MA.fail_at = 0;
                char why[200] = "";
                for (int round = 0; round < 2 && !*why; round++) {
                        if (round == 0) {
                                if (ext4_dir_open(&inode, &fa) || !fa.private_data) { sprintf(why, "open failed"); break; }
                        }
                        struct dir_private_info *ia = fa.private_data;
                        MA.fail_at = rnd() % 4 == 0 ? MA.allocs + 1 + rnd() % 4 : 0;
                        int done = 0, r = 0;
                        for (int i = 0; i < m; i++) { r = ext4_htree_store_dirent(&fa, hash[i], minor[i], &de[i], &nm[i]); if (r) break; done++; }
                        MA.fail_at = 0;
                        if (r && r != -ENOMEM) { sprintf(why, "returned %d", r); break; }
                        if (r && MA.fail_at == 0 && done == m) { sprintf(why, "failed with nothing to fail"); break; }
                        struct dir_private_info *ic = calloc(1, sizeof *ic); fc.private_data = ic;
                        for (int i = 0; i < done; i++) if (ext4_htree_store_dirent_c(&fc, hash[i], minor[i], &de[i], &nm[i])) { sprintf(why, "the C failed"); break; }
                        if (!*why && !same_trees(ic, ia, why)) break;
                        stored += done;
                        /* the tree is thrown away and the file goes on: what it had is freed, what it makes next is whole */
                        free_rb_tree_fname(&ia->root);
                        if (ia->root.rb_node) { sprintf(why, "the tree was not emptied"); break; }
                        if (MA.live != 1) { sprintf(why, "%ld allocations live after the tree was freed (want the info alone)", MA.live); break; }
                }
                if (!*why) { kfree(fa.private_data); if (MA.live) sprintf(why, "%ld allocations live at the end", MA.live); }
                if (*why && bad++ < 5) printf("case %ld differs: %s (m %d)\n", it, why, m);
                for (int i = 0; i < m; i++) free(nm[i].name);
                free(de); free(nm);
        }
        printf("cases %ld differ %ld stores %ld\n", iters, bad, stored);
        return bad != 0;
}
"""

def harness_kernel_ports(argv):
    """The kernel functions in kernel/kernel.c against Linux's own C, call for call.

    Each port replaces a function of the kernel, so the oracle is that function:
    it is cut out of the kernel source when the harness runs (linux/ if a build
    unpacked one, KERNEL_SRC, or the pinned tarball) and never kept here, the
    files being GPL-2.0 and these tests not. The callees are stubs that record
    every call -- the reads of the block, the entries stored with their hashes,
    each error __ext4_check_dir_entry reports and in what words, the brelse and
    the buffers the fscrypt paths allocate and free -- and the structures are a
    shim of the kernel's, whose offsets are generated from the //> tags in
    kernel.c exactly as the kernel build generates them from asm-offsets.c, so
    the asm reads the shim as it will read the kernel. Random directory blocks,
    with deleted entries, "." and "..", checksum tails, encrypted and
    casefolded directories, every hash version, seeds, a start hash, failing
    reads, stores and fscrypt calls, and entries corrupted in eight ways, go
    through the C function and the asm, and every recorded call has to agree.

    It runs for each architecture there is a toolchain for: the machine's
    own, and arm64 and riscv64 under qemu-user. A copy of the oracle with one
    line changed has to disagree, or nothing here is looking. What it cannot
    reach is the kernel itself: the real offsets, the real FPU bracket, the
    real ext4 -- x86_64 boots on them; the others run the walk here and have
    not been booted.
    """
    import tarfile
    root = HARNESS_ROOT
    checks = Checks()
    version = re.search(r'\{"kernel_version", "([^"]+)"\}', (root / "src/build/build.c").read_text()).group(1)
    tarball = root / "artifacts" / ("linux-%s.tar.xz" % version)

    def kernel_file(relative):
        for candidate in (os.environ.get("KERNEL_SRC"), str(root / "linux")):
            if candidate and (Path(candidate) / relative).is_file():
                return (Path(candidate) / relative).read_text()
        if tarball.is_file():
            with tarfile.open(tarball) as archive:
                return archive.extractfile("linux-%s/%s" % (version, relative)).read().decode()
        return None

    sources = {name: kernel_file(name) for name in ("fs/ext4/namei.c", "fs/ext4/dir.c", "fs/ext4/hash.c", "fs/crypto/fname.c", "fs/libfs.c", "fs/fs_dirent.c", "fs/readdir.c", "fs/ext4/dir.c", "fs/ext4/ext4.h")}
    if not all(sources.values()):
        print("kernel ports: NOT RUN -- no kernel source (linux/, KERNEL_SRC or artifacts/linux-%s.tar.xz)" % version)
        return 0

    def cut(text, head, tail, inclusive=False):
        start = text.index(head)
        end = text.index(tail, start) + (len(tail) if inclusive else 0)
        return text[start:end]

    hash_code = cut(sources["fs/ext4/hash.c"], "#define DELTA 0x9E3779B9", "/*\n * Returns the hash of a filename.")
    dir_code = (cut(sources["fs/ext4/dir.c"], "static bool is_fake_dir_entry(struct ext4_dir_entry_2 *de)", "\n}\n", True) + "\n" +
                cut(sources["fs/ext4/dir.c"], "int __ext4_check_dir_entry(const char *function, unsigned int line,", "\n}\n", True))
    match_code = (cut(sources["fs/crypto/fname.c"], "bool fscrypt_match_name(const struct fscrypt_name *fname,", "\n}\n", True) + "\n" +
                  cut(sources["fs/ext4/namei.c"], "static bool ext4_match(struct inode *parent,", "\n}\n", True).replace("static bool ext4_match(", "bool ext4_match(", 1))

    def oracle_of(name, header):
        text = cut(sources["fs/ext4/namei.c"], header, "\n}\n", True)
        return "#define %s %s_c\n%s#undef %s\n" % (name, name, text, name)

    dirent_code = KERNEL_PORTS_DIRENT_SHIM + sources["fs/fs_dirent.c"][sources["fs/fs_dirent.c"].index("static const unsigned char fs_dtype_by_ftype"):]
    libfs_code = "\n".join(cut(sources["fs/libfs.c"], head, "\n}\n", True) for head in (
        "static struct dentry *find_positive_dentry(struct dentry *parent,", "static bool offset_dir_emit(", "static void offset_iterate_dir("))
    readdir_code = "\n".join(cut(sources["fs/readdir.c"], head, tail, True) for head, tail in (
        ("struct getdents_callback64 {", "};"), ("static int verify_dirent_name(", "\n}\n"), ("static bool filldir64(", "\n}\n")))
    libfs_code = KERNEL_PORTS_LIBFS_PRELUDE + readdir_code.replace("static bool filldir64(", "bool filldir64(", 1) + "\n" + libfs_code.replace("static void offset_iterate_dir(", "static void offset_iterate_dir_c(", 1)
    def ext4dir_oracle():
        dirc, exth = sources["fs/ext4/dir.c"], sources["fs/ext4/ext4.h"]
        code = "\n".join((
            cut(dirc, "struct fname {", "};", True),
            cut(dirc, "static inline int is_32bit_api(void)", "\n}\n", True),
            cut(dirc, "static inline loff_t hash2pos(", "\n}\n", True),
            cut(exth, "static const unsigned char ext4_filetype_table[] = {", "};", True),
            cut(exth, "static inline  unsigned char get_dtype(", "\n}\n", True),
            "#define call_filldir call_filldir_c\n" + cut(dirc, "static int call_filldir(", "\n}\n", True) + "\n#undef call_filldir\n"))
        return KERNEL_PORTS_EXT4DIR_PRELUDE + code

    def arena_oracle():
        dirc = sources["fs/ext4/dir.c"]
        text = cut(dirc, "struct fname {", "};", True) + "\n#define ext4_htree_store_dirent ext4_htree_store_dirent_c\n" + \
               cut(dirc, "int ext4_htree_store_dirent(struct file *dir_file,", "\n}\n", True) + "\n#undef ext4_htree_store_dirent\n"
        return KERNEL_PORTS_ARENA_PRELUDE + text.replace("int ext4_htree_store_dirent_c", "int ext4_htree_store_dirent_c", 1)

    ports = {
        "ext4_htree_store_dirent": (arena_oracle(), KERNEL_PORTS_ARENA_TEST,
                                    "new_fn->file_type = dirent->file_type;", "new_fn->file_type = 0;"),
        "call_filldir": (KERNEL_PORTS_LIBFS_PRELUDE + readdir_code.replace("static bool filldir64(", "bool filldir64(", 1) + "\n" + ext4dir_oracle(),
                         KERNEL_PORTS_EXT4DIR_TEST, "info->extra_fname = fname;", "info->extra_fname = NULL;"),
        "offset_iterate_dir": (libfs_code, KERNEL_PORTS_LIBFS_TEST, "ctx->pos = DIR_OFFSET_EOD;", "ctx->pos = DIR_OFFSET_EOD - 1;"),
        "htree_dirblock_to_tree": (oracle_of("htree_dirblock_to_tree", "static int htree_dirblock_to_tree(struct file *dir_file,"),
                                   KERNEL_PORTS_HTREE_TEST, "count++;", "count += 2;"),
        "ext4_find_dest_de": (oracle_of("ext4_find_dest_de", "int ext4_find_dest_de(struct inode *dir, struct buffer_head *bh,"),
                              KERNEL_PORTS_FIND_TEST, "return -EEXIST;", "return -EEXIST - 1;"),
    }
    kernel_c = (root / "kernel/kernel.c").read_text()

    def tags(arch):
        """The tags of the blocks that are for this architecture, as (verb, rest) pairs."""
        found, block, limited, allowed = [], [], False, False
        for line in kernel_c.splitlines() + [""]:
            if line.startswith("//> "):
                words = line[4:].split()
                if words[0] == "arch":
                    limited, allowed = True, allowed or arch in words[1:]
                else:
                    block.append((words[0], line[4:].split(None, 1)[1] if len(words) > 1 else ""))
                continue
            if block or limited:
                if not limited or allowed:
                    found += block
                block, limited, allowed = [], False, False
        return found

    def macros(arch):
        kind = "%function" if arch == "arm64" else "@function"
        config = {"x86_64": "CONFIG_X86_64", "arm64": "CONFIG_ARM64", "riscv64": "CONFIG_RISCV"}[arch]
        return (("#define MW_GET_CURRENT \"adrp x8, current_task\\n   ldr x8, [x8, :lo12:current_task]\\n\"\n" if arch == "arm64" else "") +
                ("#define CONFIG_IA32_EMULATION 1\n" if arch == "x86_64" else "") +
                ("#define MW_GET_CURRENT_RV \"la t5, current_task\\n   ld t5, 0(t5)\\n\"\n" if arch == "riscv64" else "") +
                "#define %s 1\n#define CONFIG_FS_ENCRYPTION 1\n#define __stringify_1(x...) #x\n#define __stringify(x...) __stringify_1(x)\n"
                "#define module_param_named(a, b, c, d)\n#define ASM_RET \"ret\\n\"\n"
                '#define ASM_FUNC(name) ".globl " #name "\\n.type " #name ", %s\\n" #name ":\\n"\n'
                '#define ASM_END(name) ".size " #name ", .-" #name "\\n"\n') % (config, kind)

    library = (root / "src/lib.c").read_text()
    head = library.index("#ifdef KERNEL_MODE\n#if X64\n__asm__(\n    ASM_SIMD_SECTION\n    ASM_FUNC(hash_half_md4_wide)")
    wide_region = library[head:library.index("#endif // KERNEL_MODE\n", head) + len("#endif // KERNEL_MODE\n")]

    # every build of kernel.c on x86_64 links the readdir port, which names filldir64 to know its caller
    stub_actor = "bool filldir64(void *c, const char *n, int l, long long o, unsigned long long i, unsigned t) { return false; }\n"

    def run(arch, compiler, runner, cflags, count, sabotage, port):
        with tempfile.TemporaryDirectory() as directory:
            work = Path(directory)
            (work / "generated").mkdir()
            (work / "shim.h").write_text(KERNEL_PORTS_SHIM)
            lines = ['#include "shim.h"', "int main(void) {"]
            for verb, rest in tags(arch):
                words = rest.split(None, 2)
                if verb == "offset":
                    lines.append('printf("#define %s %%zu\\n", offsetof(struct %s, %s));' % (words[0], words[1], words[2]))
                elif verb == "const":
                    lines.append('printf("#define %s %%ld\\n", (long)(%s));' % (words[0], rest.split(None, 1)[1]))
            lines.append("return 0; }")
            (work / "offsets.c").write_text("\n".join(lines))
            built = subprocess.run(["cc", "-w", "-o", str(work / "offsets"), str(work / "offsets.c")], capture_output=True, text=True)
            if built.returncode:
                print("  the offsets did not build for %s: %s" % (arch, built.stderr[-500:]))
                return None
            (work / "generated/asm-offsets.h").write_text(
                subprocess.run([str(work / "offsets")], capture_output=True, text=True).stdout)
            (work / "kernel.c").write_text(kernel_c)
            (work / "port.c").write_text(macros(arch) + '#include "kernel.c"\n')
            oracle_text, test_text, plain, broken_text = ports[port]
            walk_text = oracle_text.replace(plain, broken_text, 1) if sabotage else oracle_text
            defines = {"x86_64": "-DCONFIG_X86_64", "arm64": "-DCONFIG_ARM64", "riscv64": "-DCONFIG_RISCV"}[arch]
            (work / "oracle.c").write_text(KERNEL_PORTS_SHIM + hash_code + "\n" + dir_code + "\n" + match_code + "\n" + dirent_code + "\n" + walk_text + (stub_actor if port not in ("offset_iterate_dir", "call_filldir") else "") + KERNEL_PORTS_COMMON + test_text)
            objects = [str(work / "oracle.c"), str(work / "port.c")]
            if arch == "x86_64":
                (work / "wide.c").write_text(
                    '#define KERNEL_MODE 1\n#define X64 1\n#define ASM_SIMD_SECTION ""\n#define ASM_SIMD_SECTION_END ""\n'
                    '#define ASM_FUNC(name) ".globl " #name "\\n.type " #name ", @function\\n" #name ":\\n"\n'
                    '#define ASM_END(name) ".size " #name ", .-" #name "\\n"\n#define ASM_RET "ret\\n"\n' + wide_region)
                objects.append(str(work / "wide.c"))
            built = subprocess.run(compiler + cflags + [defines, "-DCONFIG_FS_ENCRYPTION=1", "-DCONFIG_UNICODE=1", "-O2", "-w", "-Wl,--allow-multiple-definition", "-I", str(work), "-o", str(work / "test")] + objects,
                                   capture_output=True, text=True)
            if built.returncode:
                print("  build failed for %s:\n%s" % (arch, built.stderr[-1500:]))
                return None
            ran = subprocess.run(runner + [str(work / "test"), str(count)], capture_output=True, text=True, timeout=3000)
            found = re.search(r"cases (\d+) differ (\d+) stores (\d+)", ran.stdout)
            if not found:
                print("  no answer from %s: %s" % (arch, (ran.stdout + ran.stderr)[-500:]))
                return None
            for line in ran.stdout.splitlines():
                if line.startswith(("case ", "locks taken")) and not sabotage:
                    print("    " + line)
            return tuple(int(x) for x in found.groups())

    machine = platform.machine().lower()
    targets = []
    if sys.platform.startswith("linux") and machine in ("x86_64", "amd64"):
        targets.append(("x86_64", shlex.split(os.environ.get("CC", "cc")), [], ["-static"], 6000))
    elif sys.platform.startswith("linux") and machine in ("aarch64", "arm64"):
        targets.append(("arm64", shlex.split(os.environ.get("CC", "cc")), [], ["-static"], 6000))
    if machine not in ("aarch64", "arm64") and shutil.which("aarch64-linux-gnu-gcc") and shutil.which("qemu-aarch64"):
        targets.append(("arm64", ["aarch64-linux-gnu-gcc"], ["qemu-aarch64"], ["-static"], 1500))
    if machine != "riscv64" and shutil.which("riscv64-linux-gnu-gcc") and shutil.which("qemu-riscv64"):
        targets.append(("riscv64", ["riscv64-linux-gnu-gcc"], ["qemu-riscv64", "-cpu", "rv64,v=true,vlen=128"], ["-static", "-march=rv64gc"], 1500))
    if not targets:
        print("kernel ports: NOT RUN -- no toolchain for any architecture here")
        return 0
    for arch, compiler, runner, cflags, count in targets:
        replaced = {rest.split()[1] for verb, rest in tags(arch) if verb == "replace"}
        if not replaced:
            print("kernel ports: %s has no port to test" % arch)
            continue
        for port in ports:
            if port not in replaced:
                continue
            plain = run(arch, compiler, runner, cflags, count, False, port)
            checks(plain is not None, "%s %s: built and ran" % (arch, port))
            if plain:
                cases, bad, stores = plain
                checks(bad == 0 and stores > 500, "%s %s: %d cases, %d entries, %d differ from the kernel's C" % (arch, port, cases, stores, bad))
                broken = run(arch, compiler, runner, cflags, min(count, 600), True, port)
                checks(broken is not None and broken[1] > 0, "%s %s: an oracle with one line changed is caught" % (arch, port))
    return checks.verdict("kernel ports: checks passed", "kernel-ports")


# ----------------------------------------------------------------------------
#       The generator's odd multiples, affine, for ECDSA verify.
# ----------------------------------------------------------------------------

G_TABLE_BEGIN = "/* g_tables begin (python3 test/differential.py --harness g_tables --write) */"
G_TABLE_END = "/* g_tables end */"


def g_table_text(source):
    """The C text between the markers: (2j + 1) G for j below 32 on P-256 and
    P-384, x and y in Montgomery form (times 2^256 or 2^384 mod p), as limbs,
    least significant first. The generator's coordinates are read from the
    same net.c, so the table cannot name another point than the code does."""
    def bytes_of(name):
        found = re.search(r"static const p8 %s\[\d+\] = \{([^}]*)\};" % name, source, re.S)
        return int("".join(re.findall(r"0x([0-9a-fA-F]{2})", found.group(1))), 16)

    curves = (("p256", 256, 4, (1 << 256) - (1 << 224) + (1 << 192) + (1 << 96) - 1),
              ("p384", 384, 6, (1 << 384) - (1 << 128) - (1 << 96) + (1 << 32) - 1))
    out = [G_TABLE_BEGIN,
           "/* (2j + 1) G for j below 32, affine, x then y in Montgomery form, as",
           "   limbs, least significant first: ECDSA verify adds them to its",
           "   accumulator by the mixed formulas with the width-7 digits of u1. */"]
    for name, bits, limbs, p in curves:
        gx, gy = bytes_of("crypto_%s_gx_be" % name), bytes_of("crypto_%s_gy_be" % name)

        def add(a, b):
            if a is None:
                return b
            if b is None:
                return a
            if a[0] == b[0]:
                if (a[1] + b[1]) % p == 0:
                    return None
                slope = (3 * a[0] * a[0] - 3) * pow(2 * a[1], -1, p) % p
            else:
                slope = (b[1] - a[1]) * pow(b[0] - a[0], -1, p) % p
            x = (slope * slope - a[0] - b[0]) % p
            return (x, (slope * (a[0] - x) - a[1]) % p)

        g = (gx, gy)
        twice = add(g, g)
        point = g
        out.append("static const p64 crypto_%s_g_table[32][%d] = {" % (name, 2 * limbs))
        for _ in range(32):
            words = []
            for coordinate in point:
                montgomery = coordinate * (1 << bits) % p
                words += ["0x%016xull" % ((montgomery >> (64 * i)) & ((1 << 64) - 1)) for i in range(limbs)]
            out.append("    {" + ", ".join(words[:limbs]) + ",")
            out.append("     " + ", ".join(words[limbs:]) + "},")
            point = add(point, twice)
        out.append("};")
    out.append(G_TABLE_END)
    return "\n".join(out)


HOT_ORDER_COMMANDS = [
    ":", "echo hi", "echo hi | cat > /dev/null", "ls /tmp > /dev/null",
    "x=$(echo a); echo $x > /dev/null", "for i in 1 2 3; do echo $i; done > /dev/null",
    "cat /etc/hostname > /dev/null", "wget -q -O /dev/null http://127.0.0.1:1/ 2> /dev/null",
    "[ -f /etc/hostname ] && echo yes > /dev/null", "grep -c a /etc/hostname > /dev/null",
    "sed s/a/b/ /etc/hostname > /dev/null", "sort /etc/hostname > /dev/null",
    "cp /etc/hostname /tmp/hot-order.$$; rm /tmp/hot-order.$$", "date > /dev/null",
    "find /tmp -maxdepth 1 > /dev/null", "awk '{print}' /etc/hostname > /dev/null",
    "printf '%s\\n' a > /dev/null", "test -n a", "wc -l /etc/hostname > /dev/null",
    "mkdir -p /tmp/hot-order; rmdir /tmp/hot-order", "head -1 /etc/hostname > /dev/null",
    "tr a b < /etc/hostname > /dev/null", "if true; then echo a; fi > /dev/null",
    "case a in a) echo b;; esac > /dev/null", "f() { echo $1; }; f x > /dev/null",
    "export A=1; env > /dev/null",
]


def harness_hot_order(argv):
    """Write the order of the hot functions in src/build/spark.ld.

        python3 test/differential.py --harness hot_order SHELL MAP [--write]

    SHELL is a shell built for x86_64 with symbols and -ffunction-sections,
    MAP its link map (-Wl,-Map=MAP). Every command of HOT_ORDER_COMMANDS is
    run under qemu-user with its translation blocks logged (exact, where
    perf's instruction sampling is throttled), each block address is named by
    nm, and the functions come out ordered by how many of the commands
    executed them, each as its own input section from the map. A text fault
    maps sixteen pages of the file and the exit unmaps them: about a
    microsecond a 64 KB window, measured, and a start went from seventeen
    windows to eleven with this list in front. Assembly routines are left to
    their own block in the script (riscv64's jal reaches a megabyte), ordered the same way.
    Without --write the block is printed."""
    args = [a for a in argv if not a.startswith("--")]
    if len(args) != 2:
        print("hot_order: SHELL MAP [--write]", file=sys.stderr)
        return 2
    shell, mapfile = args
    symbols = []
    for line in subprocess.run(["nm", "-n", "-S", shell], text=True,
                               stdout=subprocess.PIPE).stdout.splitlines():
        part = line.split()
        if len(part) == 4 and part[2] in "tTwW":
            symbols.append((int(part[0], 16), int(part[1], 16), part[3]))
    symbols.sort()
    starts = [entry[0] for entry in symbols]
    sections = set(re.findall(r"^ (\.text[^\s]*)", Path(mapfile).read_text(errors="replace"),
                              re.M))
    asm = set()
    for source in (HARNESS_ROOT / "src").rglob("*"):
        if source.suffix in (".c", ".inc"):
            asm.update(re.findall(r"ASM_(?:LOCAL_)?FUNC\((\w+)\)", source.read_text(errors="replace")))
    count = {}
    with tempfile.TemporaryDirectory(prefix="moonwater-hot-order-") as temporary:
        log = Path(temporary) / "blocks"
        for command in HOT_ORDER_COMMANDS:
            log.unlink(missing_ok=True)
            subprocess.run(["qemu-x86_64", "-cpu", "max", "-d", "exec,nochain", "-D", str(log),
                            shell, "-c", command], stdout=subprocess.DEVNULL,
                           stderr=subprocess.DEVNULL, timeout=120)
            seen = set()
            for address in set(re.findall(r"\[[0-9a-f]+/([0-9a-f]+)/", log.read_text(errors="replace"))):
                at = int(address, 16)
                found = bisect.bisect_right(starts, at) - 1
                if found >= 0 and at < symbols[found][0] + max(symbols[found][1], 1):
                    seen.add(symbols[found][2])
            for name in seen:
                count[name] = count.get(name, 0) + 1

    def section_for(name):
        base = name[:-5] if name.endswith(".cold") else name
        for candidate in ([".text.unlikely." + base] if name.endswith(".cold") else
                          [".text.hot." + base, ".text." + base, ".text.startup." + base,
                           ".text.unlikely." + base]):
            if candidate in sections:
                return candidate
        return None

    ordered = []
    ordered_asm = []
    for name, ran in sorted(count.items(), key=lambda item: (-item[1], item[0])):
        if re.sub(r"(\.(part|constprop|isra|cold)(\.[0-9]+)*)+$", "", name) in asm or name in asm:
            found = ".text." + name
            if found in sections and found not in ordered_asm:
                ordered_asm.append(found)
            continue
        found = section_for(name)
        if found and found not in ordered:
            ordered.append(found)
    block = "".join("                *(%s)\n" % found for found in ordered)
    block_asm = "".join("                *(%s)\n" % found for found in ordered_asm)
    if "--write" not in argv:
        print(block, end="")
        print("# assembly")
        print(block_asm, end="")
        return 0
    path = HARNESS_ROOT / "src/build/spark.ld"
    text = path.read_text()
    begin = text.index("/* hot_order begin */\n") + len("/* hot_order begin */\n")
    end = text.index("                /* hot_order end */")
    text = text[:begin] + block + text[end:]
    begin = text.index("/* hot_asm begin */\n") + len("/* hot_asm begin */\n")
    end = text.index("                /* hot_asm end */")
    path.write_text(text[:begin] + block_asm + text[end:])
    print("hot order: %d functions and %d assembly routines of %d executed, written"
          % (len(ordered), len(ordered_asm), len(count)))
    return 0


def harness_g_tables(argv):
    """Check (or with --write, write) the table of the generator's odd
    multiples in src/net/net.c against what Python's own arithmetic gives.
    The C side compares every entry with the library's own point code
    (CHECK_net), so the two computations are independent."""
    path = HARNESS_ROOT / "src/net/net.c"
    source = path.read_text()
    begin = source.find(G_TABLE_BEGIN)
    end = source.find(G_TABLE_END)
    if begin < 0 or end < 0:
        if "--write" not in argv:
            print("g tables: no table in net.c", file=sys.stderr)
            return 1
        print("g tables: put the two marker lines where the table goes first", file=sys.stderr)
        return 1
    current = source[begin:end + len(G_TABLE_END)]
    wanted = g_table_text(source)
    if "--write" in argv:
        if current != wanted:
            path.write_text(source[:begin] + wanted + source[end + len(G_TABLE_END):])
        print("g tables: written")
        return 0
    ok = current == wanted
    print("g tables %d/1" % (1 if ok else 0))
    write_tally("g-tables", 1 if ok else 0, 1)
    return 0 if ok else 1


